-- Massawe Enteprice production schema. Apply in Supabase SQL editor.
create extension if not exists pgcrypto;
create type public.order_status as enum ('pending','processing','fulfilled','shipped','cancelled','refunded');
create type public.payment_status as enum ('unpaid','pending','paid','failed','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'customer' check(role in ('owner','admin','staff','customer')), created_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id) on delete set null, full_name text not null, email text not null, phone text, created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), title text not null, description text, sku text unique, product_type text, emoji text default '📦', price_tzs numeric(14,2) not null check(price_tzs>=0), price_usd numeric(12,2) check(price_usd is null or price_usd>=0), inventory_quantity integer not null default 0 check(inventory_quantity>=0), status text not null default 'draft' check(status in ('active','draft','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.discounts(id uuid primary key default gen_random_uuid(), code text not null unique, discount_type text not null check(discount_type in ('percentage','fixed')), discount_value numeric(12,2) not null check(discount_value>0), is_active boolean not null default true, starts_at timestamptz, ends_at timestamptz, usage_limit integer, usage_count integer not null default 0, created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), order_number text unique not null default ('ME-'||upper(substr(encode(gen_random_bytes(6),'hex'),1,10))), customer_id uuid references public.customers(id), currency text not null check(currency in ('TZS','USD')), subtotal_tzs numeric(14,2) not null default 0, total_tzs numeric(14,2) not null default 0, total_usd numeric(12,2), status public.order_status not null default 'pending', payment_status public.payment_status not null default 'unpaid', shipping_address jsonb, created_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id), title_snapshot text not null, quantity integer not null check(quantity>0), unit_price_tzs numeric(14,2) not null check(unit_price_tzs>=0), line_total_tzs numeric(14,2) not null);
create table public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), provider text not null, method text not null check(method in ('mpesa','airtel_money','tigo_pesa','card','bank_transfer')), provider_reference text unique, amount numeric(14,2) not null, currency text not null check(currency in ('TZS','USD')), status text not null default 'initiated', raw_event jsonb, created_at timestamptz not null default now());
create table public.shipping_rates(id uuid primary key default gen_random_uuid(), name text not null, region text not null, currency text not null default 'TZS', amount numeric(14,2) not null check(amount>=0), active boolean not null default true);
create table public.inventory_movements(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), delta integer not null, reason text not null, order_id uuid references public.orders(id), created_at timestamptz not null default now());
create index on public.orders(created_at desc); create index on public.products(status); create index on public.payments(order_id);
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('owner','admin','staff')) $$;
alter table public.profiles enable row level security; alter table public.customers enable row level security; alter table public.products enable row level security; alter table public.discounts enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.shipping_rates enable row level security; alter table public.inventory_movements enable row level security;
create policy "profile self read" on public.profiles for select using(id=auth.uid() or public.is_staff());
create policy "staff manage profiles" on public.profiles for all using(public.is_staff()) with check(public.is_staff());
create policy "public read active products" on public.products for select using(status='active' or public.is_staff());
create policy "staff manage products" on public.products for all using(public.is_staff()) with check(public.is_staff());
create policy "staff manage customers" on public.customers for all using(public.is_staff()) with check(public.is_staff());
create policy "customer read own profile" on public.customers for select using(user_id=auth.uid());
create policy "staff manage discounts" on public.discounts for all using(public.is_staff()) with check(public.is_staff());
create policy "staff manage orders" on public.orders for all using(public.is_staff()) with check(public.is_staff());
create policy "staff manage order items" on public.order_items for all using(public.is_staff()) with check(public.is_staff());
create policy "staff read payments" on public.payments for select using(public.is_staff());
create policy "staff manage shipping" on public.shipping_rates for all using(public.is_staff()) with check(public.is_staff());
create policy "staff read inventory movements" on public.inventory_movements for select using(public.is_staff());
-- Do not grant browser clients write access to payments/orders. Create orders through a trusted server function.
